  assert.deepEqual(buildReport('B,1,100\nA,2,50\nB,3,100'), {
    items: [{ sku: 'A', quantity: 2, totalCents: 100 }, { sku: 'B', quantity: 4, totalCents: 400 }],
    totalUnits: 6, totalCents: 500,
  });
});

test('empty and blank input', () => {
  assert.deepEqual(parseOrders(''), []);
  assert.deepEqual(parseOrders('  \n\r\n\n'), []);
  assert.deepEqual(buildReport(''), { items: [], totalUnits: 0, totalCents: 0 });
});

test('rejects non-string', () => {
  assert.throws(() => parseOrders(42), TypeError);
  assert.throws(() => buildReport(null), TypeError);
});

test('rejects malformed rows', () => {
  assert.throws(() => parseOrders('a,1,2'), Error);
  assert.throws(() => parseOrders('A,0,2'), Error);
  assert.throws(() => parseOrders('A,-1,2'), Error);
  assert.throws(() => parseOrders('A,1.5,2'), Error);
  assert.throws(() => parseOrders('A,1,-2'), Error);
  assert.throws(() => parseOrders('A,1,2,3'), Error);
  assert.throws(() => parseOrders('A,1'), Error);
});

test('rejects unsafe integers', () => {
  assert.throws(() => parseOrders('A,9007199254740992,1'), RangeError);
  assert.throws(() => buildReport('A,9007199254740991,2'), RangeError);
});

test('repeated SKUs distinct in parser, combined in report', () => {
  assert.deepEqual(parseOrders('A,1,10\nA,2,20'), [
    { sku: 'A', quantity: 1, unitPriceCents: 10 },
    { sku: 'A', quantity: 2, unitPriceCents: 20 },
  ]);
  assert.deepEqual(buildReport('A,1,10\nA,2,20'), {
    items: [{ sku: 'A', quantity: 3, totalCents: 50 }],
    totalUnits: 3, totalCents: 50,
  });
});"}

